#!/bin/bash
# Script to fix Prisma P1010 permission errors
# This script grants all necessary permissions for Prisma to work properly

set -e

DB_USER="${DB_USER:-puzzel_user}"
DB_NAME="${DB_NAME:-puzzel_foundation}"

echo "Fixing Prisma permissions for user: $DB_USER on database: $DB_NAME"

# Connect to database and grant permissions
psql -U "$DB_USER" -d "$DB_NAME" <<EOF
-- Grant schema permissions
GRANT ALL PRIVILEGES ON SCHEMA public TO "$DB_USER";
ALTER SCHEMA public OWNER TO "$DB_USER";

-- Grant database permissions
GRANT CONNECT ON DATABASE "$DB_NAME" TO "$DB_USER";
GRANT ALL PRIVILEGES ON DATABASE "$DB_NAME" TO "$DB_USER";
ALTER DATABASE "$DB_NAME" OWNER TO "$DB_USER";

-- Grant table permissions
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO "$DB_USER";
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO "$DB_USER";

-- Set default privileges
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO "$DB_USER";
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO "$DB_USER";

-- Grant system catalog permissions (needed for Prisma introspection)
GRANT USAGE ON SCHEMA information_schema TO "$DB_USER";
GRANT USAGE ON SCHEMA pg_catalog TO "$DB_USER";
GRANT SELECT ON ALL TABLES IN SCHEMA information_schema TO "$DB_USER";
GRANT SELECT ON ALL TABLES IN SCHEMA pg_catalog TO "$DB_USER";

-- Grant permissions on Prisma migrations table
GRANT ALL ON _prisma_migrations TO "$DB_USER";

-- Make user superuser (if possible)
ALTER USER "$DB_USER" WITH SUPERUSER;

-- Set database search path
ALTER DATABASE "$DB_NAME" SET search_path TO public;

EOF

echo "Permissions fixed! Try running 'npx prisma migrate status' again."
